func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestCountEven(t *testing.T) {
	tests := []struct {
		name string
		nums []int
		want int
	}{
		{
			name: "mixed values",
			nums: []int{1, 2, 3, 4, 5, 6},
			want: 3,
		},
		{
			name: "negative values",
			nums: []int{-4, -3, -2, -1, 0},
			want: 3,
		},
		{
			name: "no even values",
			nums: []int{1, 3, 5},
			want: 0,
		},
		{
			name: "empty slice",
			nums: []int{},
			want: 0,
		},
		{
			name: "nil slice",
			nums: nil,
			want: 0,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := countEven(tt.nums); got != tt.want {
				t.Fatalf("countEven(%v) = %d, want %d", tt.nums, got, tt.want)
			}
		})
	}
}

